#include <bits/stdc++.h>
using namespace std;
int main(){
    unsigned long long n;
    while(cin>>n && n!=0){
        unsigned long long root = (unsigned long long)sqrtl((long double)n);
        while(root*root>n) root--;
        while((root+1)*(root+1)<=n) root++;
        cout << (root*root==n ? "yes" : "no") << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    unsigned long long n;
    while(cin>>n && n!=0){
        int root = (int)sqrtl((long double)n);
        while((long long)root*root>(long long)n) root--;
        while((long long)(root+1)*(root+1)<=(long long)n) root++;
        cout << (root*root==(int)n ? "yes" : "no") << "\n";
    }
}

